<?php include "db.php"; $msg=""; if(isset($_POST['register'])){$name=trim($_POST['name']);$email=trim($_POST['email']);$password=$_POST['password'];$phone=trim($_POST['phone']);if($name===""||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<6){$msg="Enter a name, valid email, and password with at least 6 characters.";}else{$hash=password_hash($password,PASSWORD_DEFAULT);$stmt=mysqli_prepare($conn,"INSERT INTO users(name,email,password,phone,role) VALUES(?,?,?,?,'user')");mysqli_stmt_bind_param($stmt,"ssss",$name,$email,$hash,$phone);if(mysqli_stmt_execute($stmt)){$msg="Registration successful. You can now log in.";}else{$msg="This email may already be registered.";}}} ?>
<!DOCTYPE html><html><head><title>Register</title><link rel="stylesheet" href="style.css"></head><body><header><h1>GoBus</h1><nav><a href="index.php">Home</a><a href="login.php">Login</a></nav></header><div class="container"><div class="form-box"><h2>Create Account</h2><?php if($msg)echo '<p class="message">'.htmlspecialchars($msg).'</p>'; ?><form method="post"><label>Full Name</label><input name="name" required><label>Email</label><input type="email" name="email" required><label>Phone</label><input name="phone"><label>Password (minimum 6 characters)</label><input type="password" name="password" minlength="6" required><button name="register">Register</button></form></div></div></body></html>